// Generates TypeScript types from the shared JSON Schemas.
// Run with:  npm run gen:types
// The schemas in packages/shared-schemas are the single source of truth
// shared with the backend, so never edit src/types/generated by hand.
import { compileFromFile } from 'json-schema-to-typescript'
import { mkdir, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const schemaDir = path.resolve(here, '../../../packages/shared-schemas')
const outDir = path.resolve(here, '../src/types/generated')

const schemas = ['requirements', 'architecture', 'prediction']

await mkdir(outDir, { recursive: true })
for (const name of schemas) {
  const ts = await compileFromFile(path.join(schemaDir, `${name}.schema.json`), {
    bannerComment: `/* AUTO-GENERATED from packages/shared-schemas/${name}.schema.json. DO NOT EDIT. */`,
    additionalProperties: false,
  })
  await writeFile(path.join(outDir, `${name}.ts`), ts)
  console.log(`generated ${name}.ts`)
}
